def extend(spec):
    Q = lambda k, a, b=None: span(spec, k, a, b)
    P = []
    P.append(dict(text='Boscán y la conversación de Granada\nGarcilaso no introdujo solo el verso italiano. Su amigo Juan Boscán, barcelonés nacido hacia 1490, es conocido fundamentalmente por haber introducido la métrica italianizante (el endecasílabo y estrofas como la octava rima, el terceto y el soneto) y el petrarquismo en la poesía castellana junto con Garcilaso. La fuente sobre el endecasílabo cuenta que Boscán se convenció en Granada, en 1526, por el embajador veneciano Andrea Navagero, para que ensayase la métrica italiana. Boscán había cultivado antes la lírica cancioneril; tradujo además El Cortesano de Castiglione (1534), en una prosa modélica. La fuente inglesa resume su fama: es el primer poeta catalán que escribió en español y es famoso por incorporar el endecasílabo.',
        quotes=[Q('es_boscan', 'Es conocido fundamentalmente por haber introducido la métrica italianizante'), Q('es_endecasilabo', 'convencido en Granada por el embajador veneciano Andrea Navagiero'), Q('es_boscan', 'tradujo al español El Cortesano de Baltasar Castiglione'), Q('en_boscan', 'was the first Catalonian poet to write in Spanish')]))
    P.append(dict(text='Un libro de 1543\nLos poemas de Garcilaso no se publicaron en vida. En marzo de 1542 Boscán y su mujer firmaron un contrato para publicar un tomo titulado Las obras de Boscán y algunas de Garcilaso de la Vega; al año siguiente, bajo la dirección de la viuda de Boscán, se terminó la impresión en Barcelona (Carles Amorós, 1543). Dos reimpresiones furtivas aparecieron enseguida, una en Barcelona y otra en Lisboa, y en 1544 dos autorizadas, en Medina del Campo y en Amberes; durante los trece años siguientes apareció al menos una reimpresión cada año. La fuente inglesa añade que la primera edición anotada, y la más famosa, apareció en 1574.',
        quotes=[Q('es_garcilaso', 'En marzo de 1542, Boscán y su mujer firmaron un contrato para la publicación de un tomo titulado Las obras de Boscán y algunas de Garcilaso de la Vega.'), Q('es_garcilaso', 'Barcelona: Carles Amorós, 1543'), Q('es_garcilaso', 'durante los trece años siguientes aparecía por lo menos una reimpresión cada año'), Q('en_garcilaso', 'His poetry was published posthumously by Juan Boscán in 1543')]))
    P.append(dict(text='Los que no querían el verso nuevo\nLas innovaciones de Garcilaso y Boscán fueron imitadas en la corte, pero hubo resistencia: Cristóbal de Castillejo, partidario de los antiguos metros castellanos, se quejó con respeto de las novedades en sátiras contra el nuevo estilo. Era una disputa entre renacentistas, y la fuente aclara que Castillejo tenía también el espíritu del Renacimiento y un concepto más nacionalista de él. El endecasílabo, sin embargo, arraigó junto al octosílabo como el verso más usado en la lírica española, y el dodecasílabo, de ritmo más machacón y menos flexible, quedó arrinconado. La razón métrica es el ritmo más flexible del endecasílabo.',
        quotes=[Q('es_garcilaso', 'partidarios de los antiguos metros castellanos como Cristóbal de Castillejo'), Q('es_boscan', 'La novedad del endecasílabo, sin embargo, arraigó al lado del octosílabo como el verso más usado en la lírica española'), Q('es_endecasilabo', 'La adaptación tuvo éxito y arrinconó, a causa de su ritmo acentual más flexible, el uso del verso de doce sílabas')]))
    P.append(dict(text='Qué es el petrarquismo\nSe llama petrarquismo a la corriente que imita el estilo, las estructuras, los tópicos y la imaginería de Petrarca. Los poetas petrarquistas cultivaron sobre todo el soneto amoroso y reunieron sus poemas en cancioneros que documentaban la historia sentimental de su amor por la dama; en ellos se observa una evolución de lo sensual a lo espiritual por influjo del platonismo. Formalmente, el petrarquismo introdujo en España el soneto y el endecasílabo como verso más utilizado. En España lo introdujeron Garcilaso y Boscán, y lo siguieron Cetina, Acuña y Herrera. Con el tiempo se volvió artificioso y frío, y en el Barroco empezó a parodiarse.',
        quotes=[Q('es_petrarquismo', 'Se denomina petrarquismo, en el género lírico, a la corriente estética que imita el estilo, las estructuras de composición, los tópicos y la imaginería'), Q('es_petrarquismo', 'Se puede observar en ellos la evolución, desde lo sensual a lo espiritual, por influjo de las teorías amorosas del platonismo'), Q('es_petrarquismo', 'Formalmente, el petrarquismo introdujo en la literatura española el soneto'), Q('es_petrarquismo', 'introdujeron el petrarquismo Garcilaso de la Vega y Juan Boscán'), Q('es_boscan', 'los motivos y estructuras del Petrarquismo en la poesía castellana')]))
    P.append(dict(text='Anatomía de un soneto\nUn soneto son catorce versos endecasílabos en dos cuartetos y dos tercetos. Aunque la distribución del contenido no es estricta, el primer cuarteto presenta el tema, el segundo lo amplía, el primer terceto reflexiona y el último remata con una reflexión grave. Desde Garcilaso hasta el modernismo, el soneto castellano tuvo una estructura fija en los ocho primeros versos (ABBA:ABBA) y más libre en los seis últimos, con combinaciones como CDE:CDE o CDC:DCD. El primer intento documentado de adaptarlo al castellano fue el del marqués de Santillana, con sus cuarenta y dos sonetos «hechos al itálico modo»; no tuvo seguidores. La fuente inglesa recuerda que en el siglo XVI apareció también el soneto isabelino, de tres serventesios y un pareado.',
        quotes=[Q('es_soneto', 'Un soneto es una composición poética compuesta por catorce versos de arte mayor, endecasílabos en su forma clásica.'), Q('es_soneto', 'puede decirse que el primer cuarteto presenta el tema del soneto, y que el segundo lo amplifica o lo desarrolla'), Q('es_soneto', 'Desde Garcilaso hasta el modernismo, el soneto castellano tuvo una estructura fija en los ocho primeros versos (ABBA:ABBA)'), Q('es_soneto', 'con sus cuarenta y dos sonetos «hechos al itálico modo»'), Q('en_boscan', 'Íñigo López de Mendoza')]))
    P.append(dict(text='El ritmo del endecasílabo\nEl endecasílabo tiene un ritmo principalmente trimembre, con tres ejes acentuales y solo ocasionalmente cuatro, de los cuales el primero es libre. Por definición su acento final cae en la décima sílaba, y el acento rítmico principal puede estar en la sexta (endecasílabo propio o a maiore) o en la cuarta o la octava (impropio o a minore). La única sílaba que nunca podrá acentuarse es la novena. Esta explicación, que parece técnica, tiene consecuencias de lectura: quien lee a Garcilaso con la oreja atenta a esos ejes percibe una cadencia continua, distinta de las pausas de los hemistiquios del arte mayor.',
        quotes=[Q('es_endecasilabo', 'el endecasílabo poseía un ritmo principalmente trimembre, tres ejes acentuales, pero solo ocasionalmente cuatro'), Q('es_endecasilabo', 'Todo endecasílabo tiene, por definición, su acento final en décima'), Q('es_endecasilabo', 'La única sílaba que nunca podrá ir acentuada es la novena'), Q('en_hendecasyllable', 'a hendecasyllable (as an adjective, hendecasyllabic) is a line of eleven syllables')]))
    P.append(dict(text='Los amores de Garcilaso\nGarcilaso se casó en 1525 con Elena de Zúñiga, en un enlace basado en un convenio de intereses. Según la biografía más reciente, tres amores marcaron su vida: Magdalena de Guzmán, la Camila de la Égloga II; Guiomar Carrillo, la Galatea de la Égloga I, de la que tuvo un hijo ilegítimo; y Beatriz de Sá. A la dama portuguesa Isabel Freyre, a la que se enamoró platónicamente en 1526, se quiere identificar con la Elisa de sus versos, aunque otra hipótesis apunta a la segunda mujer de su hermano. La crítica advierte la dificultad de leer los poemas como confesión: los nombres arcádicos son máscaras literarias y las identificaciones biográficas son hipótesis.',
        quotes=[Q('es_garcilaso', 'contrajo matrimonio en 1525 con Elena de Zúñiga'), Q('es_garcilaso', 'tres amores marcaron la vida del poeta'), Q('es_garcilaso', 'se enamoró platónicamente de una dama portuguesa de la reina, Isabel Freyre'), Q('en_garcilaso', 'He was well known in both poetic and military circles during his lifetime')]))
    P.append(dict(text='Nápoles, una escuela\nLa estancia en Nápoles fue decisiva. Garcilaso se integró en la vida intelectual de la ciudad, que giraba en torno a la Academia Pontaniana, y trabó amistad con poetas como Bernardo Tasso y Luigi Tansillo y con humanistas y teóricos. Allí descubrió a los autores italianos, entre ellos Petrarca y Sannazaro, que en 1504 había publicado La Arcadia, y fortaleció su clasicismo: redescubrió las Bucólicas de Virgilio, las Metamorfosis de Ovidio y las Odas de Horacio. Antes de Nápoles su poesía no estaba marcada por rasgos petrarquistas; después abundó en ellos. En la Égloga II se refiere a Magdalena de Guzmán, la Camila; en la Canción V, a la hostil Violante Sanseverino.',
        quotes=[Q('es_garcilaso', 'Se integró muy pronto en la vida intelectual de la ciudad, que entonces giraba en torno a la Academia Pontaniana'), Q('es_garcilaso', 'Antes de ir a Nápoles su poesía no estaba marcada por rasgos petrarquistas'), Q('es_garcilaso', 'redescubrió a Virgilio y sus Bucólicas, a Ovidio y sus Metamorfosis y a Horacio y sus Odas'), Q('en_garcilaso', 'he was the most influential poet to introduce Italian Renaissance verse forms, poetic techniques, and themes to Spain')]))
    P.append(dict(text='La espada y la pluma\nLa biografía de Garcilaso explica su fama de soldado poeta. Luchó en la guerra de las Comunidades, participó en la campaña de Fuenterrabía, en la jornada de Túnez (1535), donde fue herido de dos lanzadas, y fue nombrado maestre de campo de un tercio de infantería en la expedición contra Francia de 1536. Murió en Niza el 14 de octubre de 1536 tras el asalto a una fortaleza en Le Muy. En 1531 estuvo preso por asistir a una boda sin permiso del emperador, confinado en una isla del Danubio, que describe en su Canción III. Él mismo resumió su doble oficio en un verso: «tomando ora la espada, ora la pluma».',
        quotes=[Q('es_garcilaso', 'luchó en la guerra de las Comunidades de Castilla'), Q('es_garcilaso', 'resultó herido de dos lanzadas en la boca y en el brazo derecho'), Q('es_garcilaso', 'El poeta fue nombrado maestre de campo de un tercio de infantería'), Q('es_garcilaso', 'tomando ora la espada, ora la pluma'), Q('en_garcilaso', 'representative of the contemporaneous motif of las armas y las letras')]))
    P.append(dict(text='Lo que escribió\nLa obra poética de Garcilaso comprende cuarenta sonetos, cinco canciones, una oda en liras, dos elegías, una epístola, tres églogas, ocho coplas castellanas y tres odas y un epigrama en latín. Sus temas preferidos, dice Margot Arce, son los sentimientos de ausencia, el conflicto entre razón y pasión, el paso del tiempo y el canto de una naturaleza idílica que contrasta con el dolor del poeta. Los temas mitológicos sustituyen a los religiosos: Garcilaso no escribió ni un verso de tema religioso, y se identificaba con mitos como el de Apolo y Dafne. El paisaje es arcádico pero está instalado rigurosamente en Toledo, junto al Tajo.',
        quotes=[Q('es_garcilaso', 'compuesta por cuarenta sonetos, cinco canciones, una oda en liras, dos elegías, una epístola, tres églogas y ocho coplas castellanas'), Q('es_garcilaso', 'sus temas preferidos son los sentimientos de ausencia, el conflicto entre razón y pasión, el paso del tiempo'), Q('es_garcilaso', 'Garcilaso no escribió ni un verso de tema religioso'), Q('es_garcilaso', 'El paisaje resulta arcádico, pero instalado rigurosamente en sus predios de Toledo, al margen del río Tajo.'), Q('en_garcilaso', 'Allusions to classical myths and Greco-Latin figures, great musicality, alliteration, rhythm and an absence of religion characterize his poetry.')]))
    P.append(dict(text='Un soneto sobre el tiempo\nEl soneto XXIII, «En tanto que de rosa y azucena», condensa los temas de Garcilaso. Los dos cuartetos describen a la dama: el color de rosa y azucena en su gesto, la mirada ardiente y honesta que «enciende el corazón y lo refrena», el cabello de oro que el viento mueve. Los tercetos dan la lección: «coged de vuestra alegre primavera / el dulce fruto, antes que el tiempo airado / cubra de nieve la hermosa cumbre». Es el tópico del carpe diem y del collige, virgo, rosas: la belleza se marchita y la edad lo muda todo. Las imágenes son cromáticas (rosa, azucena, oro, nieve) y el ritmo del endecasílabo acompaña el movimiento del cabello y del tiempo.',
        quotes=[Q('ws_garcilaso23', 'En tanto que de rosa y azucena', 'enciende el corazón y lo refrena,'), Q('ws_garcilaso23', 'coged de vuestra alegre primavera', 'cubra de nieve la hermosa cumbre.'), Q('ws_garcilaso23', 'todo lo mudará la edad ligera,'), Q('es_garcilaso', 'su poesía produce una vívida sensación de tiempo y se impregna de melancolía por el transcurso de la vida')]))
    P.append(dict(text='Claridad, musicalidad, melancolía\nEl lenguaje de Garcilaso es claro y nítido, conforme a los ideales de su amigo Juan de Valdés: selección, precisión y naturalidad, prefiriendo las palabras usuales y castizas a los cultismos. Prefiere el tono íntimo y personal a la retórica y pompa de tono marcial. Cuida la musicalidad mediante la aliteración y el ritmo en torno a los tres ejes del endecasílabo; usa el epíteto para crear un mundo idealizado; es hábil en la descripción de lo fugitivo y huidizo. Su melancolía es lo que él llamó su «dolorido sentir». La crítica ha visto en esta línea la primera piedra de una corriente lírica hispánica que todavía latió en Bécquer.',
        quotes=[Q('es_garcilaso', 'El lenguaje de Garcilaso es claro y nítido, conforme a los ideales de su amigo Juan de Valdés'), Q('es_garcilaso', 'cuida especialmente la musicalidad del verso mediante el uso de la aliteración'), Q('es_garcilaso', 'Utiliza asiduamente el epíteto con la intención de crear un mundo idealizado'), Q('es_garcilaso', 'puso la primera piedra de una corriente lírica hispánica que todavía latió en la poesía de Gustavo Adolfo Bécquer'), Q('en_garcilaso', 'Garcilaso adapted the eleven-syllable line to the Spanish language in his sonetos (sonnets)')]))
    P.append(dict(text='El príncipe de los poetas castellanos\nGarcilaso fue reconocido muy pronto. Cervantes lo consideró el modelo perfecto de poeta, y desde los poetas del Siglo de Oro hasta Alberti, Miguel Hernández y Cernuda, muchos escritores lo han reconocido como «príncipe de los poetas castellanos». Alberti escribió en su Elegía a Garcilaso: «Si Garcilaso volviera, / yo sería su escudero». Su obra se convirtió, desde muy pronto, en una referencia inexcusable por la revolución métrica y estética que operó. La fuente inglesa lo dice de otro modo: aunque no fue el primero ni el único en hacerlo, fue el poeta más influyente en introducir las formas, técnicas y temas del Renacimiento italiano.',
        quotes=[Q('es_garcilaso', 'Y Miguel de Cervantes le consideró el modelo perfecto de poeta'), Q('es_garcilaso', 'Si Garcilaso volviera, / yo sería su escudero'), Q('es_garcilaso', 'se convirtió, desde muy pronto, en una referencia inexcusable para los poetas españoles'), Q('en_garcilaso', 'and his poetry has continued to be popular without interruption until the present')]))
    P.append(dict(text='Fray Luis de León\nFray Luis de León, agustino nacido en Belmonte en 1527 o 1528 y profesor en Salamanca, es uno de los poetas más importantes de la segunda fase del Renacimiento español. Era de origen judeoconverso por ambas ramas. Estuvo preso más de cuatro años, entre 1572 y 1576, por traducir el Cantar de los Cantares a lengua vulgar sin licencia y por preferir el texto hebreo a la Vulgata. La fuente inglesa lo presenta como el gran poeta de la cristianización del Renacimiento en España: tras el Concilio de Trento, las formas italianas que trajo Garcilaso se usaron para temas cristianos. Murió en 1591.',
        quotes=[Q('es_frayluis', 'es uno de los poetas más importantes de la segunda fase del Renacimiento español'), Q('es_frayluis', 'Su delito principal fue traducir el Cantar de los Cantares a la lengua vulgar sin licencia.'), Q('es_frayluis', 'Tras su estancia cautelar en prisión (del 27 de marzo de 1572 al 7 de diciembre de 1576)'), Q('en_frayluis', 'Fray Luis is generally considered the leading poet in the far-reaching Christianization of the Renaissance in Spain')]))
    P.append(dict(text='La vida retirada\nLa oda «Vida retirada» abre con una exclamación: «¡Qué descansada vida / la del que huye el mundanal ruido / y sigue la escondida / senda por donde han ido / los pocos sabios que en el mundo han sido!». Es el tópico del beatus ille, el elogio de la soledad en la naturaleza frente a la vanidad de la corte, la fama y la riqueza: «no quiero ver el ceño / vanamente severo / de quien la sangre ensalza o el dinero». El poeta quiere «vivir conmigo», «a solas, sin testigo», y planta su huerto en la ladera del monte. La estrofa es la lira, que Garcilaso había introducido, de versos de siete y once sílabas; fray Luis la desarrolló y le dio un tono propio, el de la búsqueda de serenidad.',
        quotes=[Q('ws_vida_retirada', '¡Qué descansada vida', 'los pocos sabios que en el mundo han sido!'), Q('ws_vida_retirada', 'no quiero ver el ceño', 'de quien la sangre ensalza o el dinero.'), Q('ws_vida_retirada', 'Vivir quiero conmigo,', 'a solas, sin testigo,'), Q('es_frayluis', 'Como poeta desarrolló la lira como estrofa que había introducido Garcilaso de la Vega'), Q('es_frayluis', 'el deseo de la soledad y del retiro en la naturaleza (tópico del Beatus Ille)')]))
    P.append(dict(text='Sencillo en apariencia, vehemente en el fondo\nLa crítica ha discutido el estilo de fray Luis. Menéndez Pelayo vio en él la sofrosine o equilibrio griego; la crítica actual advierte que el lenguaje y la técnica traslucen el carácter vehemente y apasionado del autor. Su estilo solo es sencillo en las imágenes, el vocabulario y los adornos: la sintaxis, constreñida por la exigente forma de la lira, recurre con frecuencia al encabalgamiento. Tiene una preferencia por la segunda persona, con exclamaciones e interrogaciones retóricas, que da a sus odas un tono oratorio y de comentario moral. Su repertorio simbólico sintetiza tres tradiciones: la grecolatina (Horacio, Virgilio), la bíblica (Salmos, Job, Cantar de los Cantares) y la poesía renacentista castellana.',
        quotes=[Q('es_frayluis', 'según Marcelino Menéndez Pelayo reflejaba la sofrosine o equilibrio griego'), Q('es_frayluis', 'la crítica actual ha hecho notar que su lenguaje y técnica traslucen el carácter vehemente y apasionado del autor'), Q('es_frayluis', 'Su afán comunicativo se expresa en una particular preferencia por la segunda persona'), Q('es_frayluis', 'la grecolatina clásica'), Q('en_frayluis', 'Luis de León')]))
    P.append(dict(text='San Juan de la Cruz\nJuan de Yepes nació en Fontiveros en 1542 y murió en Úbeda el 14 de diciembre de 1591. Reformador de la orden del Carmen y cofundador con Teresa de Jesús de los Carmelitas Descalzos, es el autor cumbre de la mística experimental cristiana; desde 1952 es patrono de los poetas en lengua española. Su obra poética consta de tres poemas mayores, Noche oscura, Cántico espiritual y Llama de amor viva, y de varios menores. Dámaso Alonso estudió sus influencias: las canciones de la época y los escritos de Garcilaso, además de la Biblia. Los tres poemas mayores deben su existencia a Garcilaso: Cántico y Noche usan la lira de la canción «Si de mi baja lira», y Llama sigue el modelo de la Canción II.',
        quotes=[Q('es_sanjuan', 'Desde 1952 es el patrono de los poetas en lengua española.'), Q('es_sanjuan', 'Su obra poética está compuesta por tres poemas considerados mayores: Noche oscura, Cántico espiritual y Llama de amor viva'), Q('es_sanjuan', 'Cántico espiritual y Noche oscura están escritos en una estrofa llamada lira'), Q('en_sanjuan', 'Both his poetry and his studies on the development of the soul are considered the summit of mystical Christian literature')]))
    P.append(dict(text='La noche oscura\nLa «Noche oscura» canta, en lira, la salida del alma hacia la unión con Dios. El poema comienza: «En una noche oscura, / con ansias, en amores inflamada / ¡oh dichosa ventura!, / salí sin ser notada / estando ya mi casa sosegada». La noche es a la vez oscuridad y guía: «sin otra luz y guía / sino la que en el corazón ardía». Y se exalta: «¡Oh noche que juntaste / Amado con amada, / amada en el Amado transformada!». La imagen del Amado y la amada, del pecho florido y de los cabellos del Amado procede del Cantar de los Cantares, que Juan de la Cruz leía como alegoría del alma que busca a Dios. La lectura religiosa y la lectura literaria se han mezclado siempre en la crítica de sus poemas.',
        quotes=[Q('ws_noche_oscura', 'En una noche oscura,', 'estando ya mi casa sosegada.'), Q('ws_noche_oscura', 'sin otra luz y guía', 'sino la que en el corazón ardía.'), Q('ws_noche_oscura', '¡Oh noche que juntaste', 'amada en el Amado transformada!'), Q('es_sanjuan', 'Para Juan, el Cantar de los cantares era una alegoría escrita por Salomón del alma que busca a Dios'), Q('es_sanjuan', 'La obra de San Juan de la Cruz ha sido, desde siempre, enfocada desde dos perspectivas, la teológica y la literaria')]))
    return P


